from typing import List
import itertools

def solve_octagon_prob(nums: List[int]) -> int:
    # Check if numbers are in ascending order and form an arithmetic progression
    def is_AP(lst):
        return all(x-y == lst[0]-lst[1] for x, y in zip(lst[1:], lst[:-1]))

    # Check if numbers can form a right triangle
    def is_right_triangle(a, b, c):
        sides = [a, b, c]
        largest = max(sides)
        return (largest**2 == sum([x**2 for x in sides]) - largest**2)

    total = 0
    successful = 0
    # Generate all possible combinations of 3 vertices from the given numbers
    for comb in itertools.combinations(nums, 3):
        if is_AP(comb) and is_right_triangle(*comb):
            successful += 1
        total += 1

    m = successful
    n = total - successful
    # Return the sum of their greatest common divisor (gcd)
    def gcd(a, b):
        while a:
            a, b = b % a, a
        return b
    return m + n + gcd(m, n) * 2
```
