from collections import defaultdict
import math

def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

# Calculate the number of ways to divide a list into groups with equal sum.
def count_ways(lst, total, groupSize):
    if not lst or total < 0:
        return 0
    elif total == 0 and len(lst) % groupSize != 0:
        return 0
    else:
        res = (total / len(lst)) * count_ways(lst[1:], total - lst[0], groupSize)
        if len(lst) >= groupSize and total >= sum(lst[:groupSize]):
            res += count_ways(lst[groupSize:], total - sum(lst[:groupSize]), groupSize)
        return int(res)

# Calculate the number of ways to arrange blades into slots.
def count_rotor_arrangements(n, blades):
    # Sort the blades in descending order so that we can divide them into groups with equal sum later.
    blades = sorted(blades)[::-1]

    total = sum(blades)
    if total % n != 0:
        return 0
    else:
        total /= n

    # Calculate the number of ways to divide the blades into groups with equal sum.
    res = 1
    for groupSize in range(1, len(blades) + 1):
        if n % groupSize == 0 and total % groupSize == 0:
            res *= count_ways(blades, total * (n / groupSize), groupSize)

    # Divide by the number of ways to arrange the blades into slots.
    return int(res / factorial(n))
