            bits = [i for i in range(n) if ((mask >> i) & 1)]
            masks[mask] = 2 ** sum((x + 1) % 3 == (y + 1) % 3 for x in bits for y in bits)
        else:
            masks[mask] = masks[(mask & -mask - 1)] | (masks[mask & -mask - 1] << 1)

    total_weights[0] = 0
    for mask in range(1, 1 << n):
